    const newItems = [...items];
    const [dragged] = newItems.splice(dragIndex.current, 1);
    newItems.splice(dropIndex, 0, dragged);
    setItems(newItems);
  };

  return (
    <ul>
      {items.map((item, i) => (
        <li draggable
            onDragStart={() => dragIndex.current = i}
            onDragOver={e => e.preventDefault()}
            onDrop={() => handleDrop(i)}>
          {item}
        </li>
      ))}
    </ul>
  );
}

